require_once __DIR__.'/includes/functions.php';expire_donations($pdo);$q=trim($_GET['q']??'');$category=$_GET['category']??'';$where="d.status IN ('Active','Partially Collected') AND d.remaining_quantity>0 AND d.expiry_at>NOW()";$params=[];if($q!==''){$where.=' AND (d.food_name LIKE ? OR d.locality LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}if(in_array($category,['Vegetarian','Non-Vegetarian','Vegan','Bakery','Fruits','Other'],true)){$where.=' AND d.category=?';$params[]=$category;}$stmt=$pdo->prepare("SELECT d.* FROM food_donations d WHERE $where ORDER BY d.created_at DESC LIMIT 6");$stmt->execute($params);$foods=$stmt->fetchAll();$donationCount=(int)$pdo->query('SELECT COUNT(*) FROM food_donations')->fetchColumn();$collected=(int)$pdo->query("SELECT COUNT(*) FROM collection_requests WHERE status='Collected'")->fetchColumn();$active=(int)$pdo->query("SELECT COUNT(*) FROM food_donations WHERE status IN ('Active','Partially Collected') AND expiry_at>NOW() AND remaining_quantity>0")->fetchColumn();$page_title='SharePlate | Share More. Waste Less.';require __DIR__.'/includes/header.php';?>
